#!/usr/bin/env python3
from __future__ import annotations

import base64
from pathlib import Path

SHE_RS = base64.b64decode(" ").decode("utf-8")
ATMOSPHERE_SH = base64.b64decode(" ").decode("utf-8")

ROOT = Path(__file__).resolve().parents[2]


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)


def main() -> None:
    she_path = ROOT / "crates/simsat/src/she.rs"
    if she_path.exists():
        raise RuntimeError(f"refusing to overwrite existing {she_path}")
    she_path.write_text(SHE_RS.rstrip() + "\n", encoding="utf-8")

    lib_path = ROOT / "crates/simsat/src/lib.rs"
    lib = lib_path.read_text(encoding="utf-8")
    lib = replace_once(lib, "pub mod solar;\n", "pub mod she;\npub mod solar;\n", "lib module export")
    lib = lib.replace("M5's SH-2 sky ambient", "M5's positive log-SH3 sky ambient")
    lib = lib.replace(
        "the aperture-occluded SH\n//!   ambient, and the water glint + Fresnel sky reflection",
        "the aperture-occluded positive SH\n//!   ambient, and the water glint + Cox-Munk sky SHE reflection",
    )
    lib_path.write_text(lib, encoding="utf-8")

    atmosphere_path = ROOT / "crates/simsat/src/atmosphere.rs"
    atmosphere = atmosphere_path.read_text(encoding="utf-8")
    start_marker = "// ── SH-2 directional sky ambient"
    end_marker = "// ── finite solar disk"
    start = atmosphere.find(start_marker)
    if start < 0:
        raise RuntimeError("atmosphere SH-2 start marker not found")
    end = atmosphere.find(end_marker, start)
    if end < 0:
        raise RuntimeError("finite-solar-disk marker not found after SH section")
    atmosphere = atmosphere[:start] + ATMOSPHERE_SH.rstrip() + "\n\n" + atmosphere[end:]
    atmosphere_path.write_text(atmosphere, encoding="utf-8")

    render_path = ROOT / "crates/simsat/src/render.rs"
    render = render_path.read_text(encoding="utf-8")
    render = replace_once(
        render,
        "// Cox-Munk wind-ruffled SUN GLINT + Fresnel SKY REFLECTION (M3), replacing the",
        "// Cox-Munk wind-ruffled SUN GLINT + prefiltered SKY SHE (M3), replacing the",
        "water heading",
    )
    old_sky = '''        // Fresnel specular sky reflection: the sky colour in the mirror-of-view
        // direction, weighted by the Fresnel reflectance at the view zenith. Uses the
        // SH sky radiance so water reflects the (coloured) sky, not just the sun.
        let cos_view = dot3(to_cam, surf_up).max(0.0);
        let f_sky =
            optics::fresnel_reflectance_unpolarized(cos_view, optics::WATER_REFRACTIVE_INDEX_VIS);
        let sky_dir = reflect(view, surf_up); // surface -> sky specular direction
        let l_sky = ctx
            .sky_sh
            .radiance(px.sun_elev_deg as f64, surf_up, sun, sky_dir);
'''
    new_sky = '''        // Positive factorized SHE prefilter of the atmospheric sky through the same
        // effective Cox-Munk slope variance as the analytic solar glint. The sky LUT
        // excludes the solar disk, so the two terms remain disjoint.
        let l_sky = ctx.sky_sh.cox_munk_sky_reflection(
            px.sun_elev_deg as f64,
            surf_up,
            sun,
            to_cam,
            mss,
        );
'''
    render = replace_once(render, old_sky, new_sky, "water sky reflection block")
    render = replace_once(render, "+ f_sky * l_sky[c];", "+ l_sky[c];", "water sky sum")
    old_reflect = '''/// Reflect `incident` about a unit `normal`: `incident - 2 (incident . n) n`.
#[inline]
fn reflect(incident: [f64; 3], normal: [f64; 3]) -> [f64; 3] {
    let d = 2.0 * dot3(incident, normal);
    [
        incident[0] - d * normal[0],
        incident[1] - d * normal[1],
        incident[2] - d * normal[2],
    ]
}

'''
    render = replace_once(render, old_reflect, "", "obsolete mirror helper")
    render_path.write_text(render, encoding="utf-8")


if __name__ == "__main__":
    main()
